package com.scriptles.cabinet.catalog.entity;
import com.scriptles.cabinet.media.enums.ExternalSource; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="collection_external_references",uniqueConstraints={@UniqueConstraint(name="uk_collection_external_provider_id",columnNames={"provider","external_id"}),@UniqueConstraint(name="uk_collection_external_owner_provider",columnNames={"collection_id","provider"})}) @Getter @Setter @NoArgsConstructor
public class CollectionExternalReference { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="collection_id",nullable=false) private Collection collection; @Enumerated(EnumType.STRING) @Column(name="provider",nullable=false,length=30) private ExternalSource provider; @Column(name="external_id",nullable=false,length=255) private String externalId; @Column(columnDefinition="TEXT") private String externalUrl; private Instant lastSyncedAt; private Instant lastSuccessfulSyncAt; private Instant lastSyncAttemptAt; @Column(nullable=false,length=20) private String syncStatus="NEVER_SYNCED"; @Column(nullable=false,length=12) private String syncPriority="WARM"; private Instant nextSyncAt; @Column(columnDefinition="TEXT") private String lastError; private UUID lastOperationId; private Instant lastDemandAt; @CreationTimestamp private Instant createdAt; @UpdateTimestamp private Instant updatedAt; }
